// Pseudo protocol for per-tenant partition reallocation
async function rebalanceTenantPartitions(tenantId, partitions, targetBrokers){
  await freezeOffsets(tenantId, partitions);
  await migrateData(partitions, targetBrokers);
  await commitOwnershipChange(tenantId, partitions, targetBrokers);
  await resumeProcessing(tenantId);
}
```

